    wr_wind_rattled_pole = area.room('wr_wind_rattled_pole', name='Wind-Rattled Pole', desc="Higher reef ridges watch the open water, where raider sails, weather lines, and whale shadows can all change a day's work. This part of the Watch Reef centers on wind-rattled pole, where reef raiders have left boot cuts near the blind side. The watch reef gives combat and scouting a civic purpose rather than random violence.", room_type='path')
    wr_far_canoe_sight = area.room('wr_far_canoe_sight', name='Far Canoe Sight', desc="Higher reef ridges watch the open water, where raider sails, weather lines, and whale shadows can all change a day's work. This part of the Watch Reef centers on far canoe sight, where wind snaps small warning flags against their poles. The watch reef gives combat and scouting a civic purpose rather than random violence.", room_type='path')
    wr_sentry_driftwood = area.room('wr_sentry_driftwood', name='Sentry Driftwood', desc="Higher reef ridges watch the open water, where raider sails, weather lines, and whale shadows can all change a day's work. This part of the Watch Reef centers on sentry driftwood, where a clear view shows how quickly the sea changes color. The watch reef gives combat and scouting a civic purpose rather than random violence.", room_type='path')
    wr_reef_shadow_edge = area.room('wr_reef_shadow_edge', name='Reef Shadow Edge', desc="Higher reef ridges watch the open water, where raider sails, weather lines, and whale shadows can all change a day's work. This part of the Watch Reef centers on reef shadow edge, where lookout shells are stacked mouth-down to stay dry. The watch reef gives combat and scouting a civic purpose rather than random violence.", room_type='path')
    wr_hooked_blade_scar = area.room('wr_hooked_blade_scar', name='Hooked Blade Scar', desc='Hooked blade scars score the coral where a lookout once forced raiders back toward open water. The ridge still funnels fights into a hard, readable line instead of scattering danger at random.', room_type='path')
    wr_rain_line_shelf = area.room('wr_rain_line_shelf', name='Rain Line Shelf', desc='Rain streaks leave pale lines on this high shelf, briefly hiding movement along the reef shadow. Raiders favor that weather, so the shelf has become a practical place to test readiness.', room_type='path')
