    sr_heavy_reptile_track = area.room('sr_heavy_reptile_track', name='Heavy Reptile Track', desc='A heavy reptile trail crosses the shell bar at dawn and returns when the sun warms the stone. The track gives players a clear loop to follow, fight, recover, and read again.', room_type='clearing')
