    sr_tide_eel_slot = area.room('sr_tide_eel_slot', name='Tide Eel Slot', desc='A narrow slot funnels tide eels, small fish, and the lizards that hunt both. Players can work the edge for practice, but the slick stone keeps each fight tied to place and footing.', room_type='clearing')
